using System.Windows;using System.Windows.Controls;namespace FFPerformanceEngine.App.Pages;public partial class ExpertPage:UserControl{public ExpertPage(){InitializeComponent();Loaded+=OnLoaded;}private void OnLoaded(object s,RoutedEventArgs e){var env=App.Services.Environment.Capture();EnvironmentText.Text=$"{env.WindowsDescription} · {env.LogicalProcessors} logical processors · RAM {(env.MemoryTotalGb?.ToString("0.0")??"—")} GB";BlueStacksText.Text=env.Instances.Count==0?"Nenhuma instância lida do bluestacks.conf.":string.Join(Environment.NewLine,env.Instances.Select(x=>$"{x.Name} · {x.AndroidVersion} · CPU {x.CpuCores?.ToString()??"—"} · RAM {x.RamMb?.ToString()??"—"} MB · Renderer {x.Renderer??"—"}"));}private async void Snapshot_Click(object s,RoutedEventArgs e){var env=App.Services.Environment.Capture();var instance=env.Instances.FirstOrDefault();if(instance is null){MessageBox.Show("Nenhuma instância BlueStacks encontrada.");return;}var values=App.Services.BlueStacks.CaptureAllowedSettings(instance.Name);var snapshot=await App.Services.Snapshots.CreateAsync("Expert snapshot",values);await App.Services.History.AppendAsync(new FFPerformanceEngine.Core.Models.HistoryEvent{Kind=FFPerformanceEngine.Core.Models.HistoryEventKind.Snapshot,Title="Snapshot criado",Summary=$"{snapshot.Name} com {snapshot.Values.Count} valores reversíveis."});MessageBox.Show($"Snapshot criado com {snapshot.Values.Count} valores.");}}